/** String.format for Android positional specifiers: %1$s, %2$d, %2$02d, %s, %d, %%. */
export function formatString(fmt, ...args) {
  let next = 0;
  return fmt.replace(/%(?:(\d+)\$)?(0)?(\d+)?([sd%])/g, (_, pos, zero, width, conv) => {
    if (conv === '%') return '%';
    const v = args[pos ? Number(pos) - 1 : next++];
    let s = conv === 'd' ? String(Math.trunc(Number(v))) : String(v ?? 'null');
    if (width) s = s.padStart(Number(width), zero ? '0' : ' ');
    return s;
  });
}

/** stringResource(R.string.x, ...args) — id is the string name. */
export const stringResource = (id, ...args) => formatString(R.string[id], ...args);

/** pluralStringResource(R.plurals.x, count, ...args) */
export const pluralStringResource = (id, count, ...args) => {
  const p = R.plurals[id];
  return formatString(count === 1 ? (p.one ?? p.other) : p.other, ...args);
};
